melanthius: { name: "Melanthius, the goatherd", role: "herd", sex: "m", hair: 0x2A1E16, beard: "short", persona: "suitor", greet: "Out of my way, beggar. The suitors want their goats." },
antinous: { name: "Antinous", role: "suitor", sex: "m", hair: 0x1A1410, beard: "short", persona: "suitor", greet: "Another beggar at the feast? Take your scraps and go." },
eurymachus: { name: "Eurymachus", role: "suitor", sex: "m", hair: 0xB8904A, persona: "suitor", greet: "The queen will choose soon. She must. And it will be me." },
amphinomus: { name: "Amphinomus", role: "suitor", sex: "m", hair: 0x5A3E26, beard: "short", persona: "suitor", greet: "Good health to you, old father. May better days come to you." },
phemius: { name: "Phemius, the bard", role: "bard", sex: "m", hair: 0x8A7A6A, beard: "full", persona: "greek", greet: "They make me sing for them. I sing; what else can a bard do?" },
medon: { name: "Medon, the herald", role: "gkman", sex: "m", hair: 0x8A8070, beard: "short", persona: "greek", greet: "I hear what the suitors plot. I tell the queen." },
laertes: { name: "Laertes", role: "herd", sex: "m", hair: 0xF0ECE4, beard: "full", persona: "greek", greet: "I dig my vines and wait. My son will not come home. Twenty years." },
argos: { name: "Argos, the old hound", dog: 1, persona: "greek", greet: "" },
nestor: { name: "Nestor", role: "king", sex: "m", hair: 0xF0ECE4, beard: "full", persona: "nestor", greet: "Welcome, strangers. Share in the sacrifice to Poseidon first; then you shall tell us who you are." },
peisistratus: { name: "Peisistratus, son of Nestor", role: "prince", sex: "m", hair: 0x3A2A1A, persona: "pylian", greet: "I'll drive you to Sparta myself, son of Odysseus. The horses are ready." },
menelaus: { name: "Menelaus", role: "king", sex: "m", hair: 0xC8A060, beard: "full", persona: "menelaus", greet: "Welcome, both of you! Eat first; then tell me whose sons you are." },
helen: { name: "Helen", role: "queen", sex: "f", hair: 0xD8B060, persona: "helen", greet: "Who is this young man? He has the very look of Odysseus." },
calypso: { name: "Calypso", role: "nymph", sex: "f", hair: 0x3A2A1A, persona: "calypso", greet: "Stay a while, wanderer. The island is quiet, and the wine is sweet." },
hermes: { name: "Hermes", role: "hermes", sex: "m", hair: 0xC8A060, persona: "hermes", greet: "Zeus sends me. I would not have chosen the long way across all that salt water myself." },
nausicaa: { name: "Nausicaa", role: "princess", sex: "f", hair: 0x3A2A1A, persona: "nausicaa", greet: "Stranger, you do not seem a bad man or a fool. Come, I will show you the way to the city." },
alcinous: { name: "Alcinous, king of the Phaeacians", role: "king", sex: "m", hair: 0x8A7A6A, beard: "full", persona: "alcinous", greet: "Welcome to our hall, stranger. Here no guest goes away unhappy." },
arete: { name: "Arete, queen of the Phaeacians", role: "queen", sex: "f", hair: 0x5A4A3A, persona: "arete", greet: "Where do you come from, stranger, and who gave you those clothes?" },
demodocus: { name: "Demodocus, the blind bard", role: "bard", sex: "m", hair: 0xE0D8CC, beard: "full", persona: "demodocus", greet: "Sit by me, friend. What song would you hear?" },
laodamas: { name: "Laodamas, son of Alcinous", role: "prince", sex: "m", hair: 0x3A2A1A, persona: "phaeacian", greet: "Will you try the games, stranger? You have the build of a fighter." },
euryalus: { name: "Euryalus", role: "gkman", sex: "m", hair: 0x1A1410, persona: "phaeacian", greet: "You look more like a trader than an athlete." },
aeolus: { name: "Aeolus, keeper of the winds", role: "king", sex: "m", hair: 0xD8D8E0, beard: "full", persona: "greek", greet: "Tell me of Troy, guest. Tell it all. The winds can wait." },
circe: { name: "Circe", role: "sorceress", sex: "f", hair: 0x8A3A1A, persona: "circe", greet: "Come in, come in. Sit. Drink. You must be weary." },
eurylochus: { name: "Eurylochus", role: "warrior", sex: "m", hair: 0x3A2A1A, beard: "short", persona: "sailor", greet: "I don't like it. I don't like any of it." },
elpenor: { name: "Elpenor", role: "sailor", sex: "m", hair: 0x6A4A2A, persona: "sailor", greet: "Is it morning already?" },
tiresias: { name: "Tiresias", role: "seer", sex: "m", hair: 0xF0ECE4, beard: "full", persona: "tiresias", greet: "Stand back from the blood, and let me drink, and I will tell you the truth." },
anticleia: { name: "Anticleia, mother of Odysseus", role: "mourner", sex: "f", hair: 0xD8D0C8, persona: "greek", greet: "My child, how did you come down here, alive, into the dark?" },
achilles: { name: "The shade of Achilles", role: "hero", sex: "m", hair: 0xD8B060, persona: "greek", greet: "Do not try to comfort me about death." },
agamemnon: { name: "The shade of Agamemnon", role: "king", sex: "m", hair: 0x8A7A6A, beard: "full", persona: "greek", greet: "Odysseus! Hear how I came home." },
polyphemus: { name: "Polyphemus", role: "giant", sex: "m", hair: 0x2A1E16, beard: "full", persona: "greek", greet: "Who are you? Where is your ship?", scale: [3.4, 3.4, 3.4] },
lampetie: { name: "Lampetie, daughter of the Sun", role: "nymph", sex: "f", hair: 0xE8B840, persona: "greek", greet: "These are my father's cattle. They are never born and they never die." },
dolius: { name: "Dolius", role: "herd", sex: "m", hair: 0xD8D0C0, beard: "full", persona: "greek", greet: "Master! Is it you? It is you!" },
eupeithes: { name: "Eupeithes, father of Antinous", role: "suitor", sex: "m", hair: 0xD8D0C0, beard: "full", persona: "suitor", greet: "My son is dead. Someone will answer for it." },
halitherses: { name: "Halitherses, the old prophet", role: "seer", sex: "m", hair: 0xE8E4DC, beard: "full", persona: "greek", greet: "I watch the birds, and the birds speak plainly." },
theoclymenus: { name: "Theoclymenus, the seer", role: "seer", sex: "m", hair: 0x3A2A1A, beard: "short", persona: "greek", greet: "I am a seer, fleeing a death in Argos. Take me aboard, son of Odysseus." },
irus: { name: "Irus, the beggar", role: "beggar", sex: "m", hair: 0x5A4A3A, beard: "short", persona: "suitor", greet: "Get off my doorstep, old man, or I'll drag you off it by the foot!" },
euryclea2: { name: "Eurynome, the housekeeper", role: "servant", sex: "f", hair: 0x9A8A7A, persona: "greek", greet: "The queen is in her room. I'll tell her you're here." },
diocles: { name: "Diocles of Pherae", role: "gkold", sex: "m", hair: 0xC8C0B0, beard: "full", persona: "greek", greet: "Two young lords on the road at nightfall! Stay the night under my roof." }
