priam: { name: "Priam, king of Troy", role: "king", sex: "m", hair: 0xF0ECE4, beard: "full", persona: "priam", greet: "Come, child. Sit by me and tell me what you see." },
antenor: { name: "Antenor", role: "gkold", sex: "m", hair: 0xE0D8CC, beard: "full", persona: "trojan", greet: "I have had Odysseus and Menelaus as guests in my house. Long ago, before all this." },
paris: { name: "Paris", role: "prince", sex: "m", hair: 0x3A2A1A, persona: "Paris, son of Priam, from Homer's Iliad: handsome, charming, careless; he took Helen from Sparta and began the war." + HGW_ERA2, greet: "Fighting is for those who like it. The gods gave me other gifts." },
iris: { name: "Iris, the messenger of the gods", role: "nymph", sex: "f", hair: 0xC8A0E0, persona: "Iris, swift messenger of the gods, from Homer's Iliad." + HGW_ERA2, greet: "I come from Zeus, quick as the rainbow." },
pandarus: { name: "Pandarus", role: "archer", sex: "m", hair: 0x3A2A1A, beard: "short", persona: "Pandarus, son of Lycaon, an archer allied with Troy, from Homer's Iliad: proud of his bow, rash." + HGW_ERA2, greet: "Sixteen palms across, the horns of this bow. I shot the goat myself." },
machaon: { name: "Machaon, the healer", role: "warrior", sex: "m", hair: 0x5A4A3A, beard: "short", persona: "Machaon, son of Asclepius, the Greeks' healer at Troy, from Homer's Iliad." + HGW_ERA2, greet: "A good healer is worth many men." },
diomedes: { name: "Diomedes", role: "warrior", sex: "m", hair: 0xB8904A, beard: "short", persona: "Diomedes, son of Tydeus, king of Argos, from Homer's Iliad: young, fearless, respectful to elders." + HGW_ERA2, greet: "I will fight while I have breath." },
idomeneus: { name: "Idomeneus of Crete", role: "king", sex: "m", hair: 0x8A7A6A, beard: "full", persona: "achaean", greet: "Eighty ships I brought from Crete." },
ajaxT: { name: "Ajax, son of Telamon", role: "warrior", sex: "m", hair: 0x3A2A1A, beard: "full", scale: 1.12, persona: "Great Ajax of Salamis, from Homer's Iliad: huge, steady, few words, the bulwark of the Greeks with his tower-like shield." + HGW_ERA2, greet: "..." },
andromache: { name: "Andromache", role: "gkveiled", sex: "f", hair: 0x2A1E16, persona: "Andromache, wife of Hector, from Homer's Iliad: loving, afraid for him; Achilles killed her father and brothers." + HGW_ERA2, greet: "You are to me father, mother, brother, Hector. You are everything." },
hecuba: { name: "Hecuba, queen of Troy", role: "queen", sex: "f", hair: 0xC8C0B8, persona: "Hecuba, queen of Troy, wife of Priam, from Homer's Iliad." + HGW_ERA2, greet: "So many sons I have lost." },
aeneas: { name: "Aeneas", role: "trojan", sex: "m", hair: 0x6A4A2A, beard: "short", persona: "Aeneas, son of Anchises and Aphrodite, leader of the Dardanians, from Homer's Iliad." + HGW_ERA2, greet: "The gods watch over my line." },
sarpedon: { name: "Sarpedon of Lycia", role: "king", sex: "m", hair: 0x3A2A1A, beard: "short", persona: "Sarpedon, son of Zeus, king of Lycia, ally of Troy, from Homer's Iliad." + HGW_ERA2, greet: "Why do they honour us in Lycia, Glaucus, if not so that we stand in the front?" },
glaucus: { name: "Glaucus of Lycia", role: "warrior", sex: "m", hair: 0xB8904A, persona: "Glaucus, Lycian ally of Troy, from Homer's Iliad: grandson of Bellerophon." + HGW_ERA2, greet: "Like leaves on trees the race of men is found." },
phoenix: { name: "Phoenix, the old tutor", role: "gkold", sex: "m", hair: 0xF0ECE4, beard: "full", persona: "Phoenix, old tutor of Achilles, from Homer's Iliad: loving, long-winded, wise." + HGW_ERA2, greet: "I taught him to speak and to fight, when he was so high." },
antilochus: { name: "Antilochus, son of Nestor", role: "warrior", sex: "m", hair: 0x3A2A1A, persona: "achaean", greet: "Fastest runner of the young men. Ask anyone." },
automedon: { name: "Automedon, the charioteer", role: "warrior", sex: "m", hair: 0x5A4A3A, beard: "short", persona: "achaean", greet: "I drive Achilles' immortal horses." }
