polydectes: { name: "King Polydectes", role: "king", sex: "m", hair: 0x3A2A1A, beard: "short", persona: "Polydectes, king of Seriphos, from Kingsley's The Heroes: greedy, cunning, cruel, and a coward." + HGW_ERA2, greet: "Am I not your king? Where is your present, then?" },
graea1: { name: "The first Gray Sister", role: "gkold", sex: "f", hair: 0xF4F4F4, persona: "graea", greet: "Why the old times were better than the new..." },
graea2: { name: "The second Gray Sister", role: "gkold", sex: "f", hair: 0xF4F4F4, persona: "graea", greet: "Give me the eye, that I may see him." },
